import {Form, type FormProps} from 'alinea/ui'
import styles from './FormView.module.css'

const views = {
  form: <form className={styles.form} />,
  row: <div className={styles.row} />,
  label: <label className={styles.label} />,
  help: <p className={styles.help} />,
  error: <p className={styles.error} />,
  control: <input className={styles.control} />,
  choice: <label className={styles.choice} />,
  section: <fieldset className={styles.section} />,
  legend: <legend className={styles.legend} />,
  item: <div className={styles.item} />,
  add: <button className={styles.add} />,
  remove: <button className={styles.remove} />,
  submit: <button className={styles.submit} />,
  confirmation: <p className={styles.confirmation} />
}

interface FormViewProps {
  definition: FormProps['definition']
  action: FormProps['action']
  upload: FormProps['upload']
}

export function FormView({definition, action, upload}: FormViewProps) {
  return (
    <Form
      definition={definition}
      views={views}
      action={action}
      upload={upload}
    />
  )
}

.form,
.section,
.item {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.form > *,
.section > *,
.item > * {
  grid-column: 1 / -1;
}
.row[data-width='half'] {
  grid-column: auto;
}
.row[data-invalid] .control {
  border-color: crimson;
}

'use client'

import {Form, FormInput, type FormInputViewProps} from 'alinea/ui'

function Textarea(props: FormInputViewProps) {
  const maxLength = props.input.attributes.maxLength
  return (
    <div className="textarea">
      <FormInput {...props} />
      {maxLength && <p className="hint">At most {maxLength} characters</p>}
    </div>
  )
}

const views = {
  textarea: Textarea
}
